return true

var wp = InputDeviceManager.get_meta("wp")
var np = tree.current_scene.deployment_controller.temp_positions[0]
return float(wp.distance_to(np))

var TS = load("res://scripts/tutorial/TutorialScript.gd")
var step = {}
for s in TutorialManager._steps:
	if str(s.get("id", "")) == "nudge_wagon":
		step = s
var txt = TS.render_text(str(step.get("prompt", {}).get("pad", "")), true)
return txt.contains("[L3]")

